(* [comment removed for export] *)
Section Run.
Variables (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
          (V2 cls r s n valp : Z) (bs : list Z).
Local Notation sp := (V2 + cls).
Local Notation spc := (V2 - 160).
Local Notation W := ((valp, 8) :: VA.ERRNO_W (pa_tp AD)).
Local Notation BX0 := ([] : list (Z * Z)).
Local Notation SCR := VA.DS_SCR.
Hypothesis Hcls : cls = 0 \/ cls = 16.
Hypothesis V32 : V2 mod 32 = 0.
Hypothesis HH : ri_inv HI (BX0 ++ LBX) FF LK cr Aw M (vml_of model).
Hypothesis AM : L5CA.amodel_ok Aw model.
Hypothesis K0 : K [].
Hypothesis ENT : VA.entryAs AD L ar R M sp r SCR.
Hypothesis FRM : VA.ffroomN VA.DS_N FF LK.
Hypothesis FRS : PMSPA.ffrsA FF sp.
Hypothesis A10 : getr R (reg 10) = Z_to_bv 64 s.
Hypothesis A11 : getr R (reg 11) = Z_to_bv 64 n.
Hypothesis A12 : getr R (reg 12) = Z_to_bv 64 valp.
Hypothesis LEN : Z.of_nat (length bs) = n.
Hypothesis Hn : 1 <= n <= WDL.SNP_MAX.
Hypothesis GNM : WDL.gnum bs = true \/ WDL.gspecial bs.
Hypothesis BYS : Forall (fun c => 0 <= c < 256) bs.
Hypothesis BAT : L5.bytes_at RSEGS M s (bs ++ [0]).
Hypothesis AO : PMSPA.aobjA FF s (n + 1).
Hypothesis SDEF : L5.defined M s (n + 1).
Hypothesis RC : VA.rcellA ar M sp valp 8.
Hypothesis V8 : valp mod 8 = 0.
Hypothesis APV : valp + 8 <= s \/ s + n + 1 <= valp.
Hypothesis BASE : PMSTA.base_okA RSEGS AD M.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (ec : Z),
    regs_preserved R R' -> getr R' (reg 11) = Z_to_bv 64 ec -> (ec = 0 \/ ec = 34) ->
    L5.bytes_at RSEGS M' s (bs ++ [0]) -> L5.defined M' valp 8 ->
    L5CA.ahpres L ar LBX FF sp SCR W M M' ->
    model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
    ri_inv HI LBX FF LK' cr Aw' M' (vml_of model') ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.

Local Notation OWN := (own13 sp R).
Local Notation OC := (ocell13 sp).

