(* [comment removed for export] *)
Lemma NONZ1 M1 model1 LK1 Aw1 x g1 cr1 (fx1 : FPState) R1 (d : Z) :
  UINV 0 M1 model1 LK1 Aw1 x g1 cr1 -> RC R1 ->
  getr R1 (reg 18) = Z_to_bv 64 F -> getr R1 (reg 25) = Z_to_bv 64 F -> getr R1 (reg 24) = Z_to_bv 64 shF ->
  reg_get (@fp_regs fx1) 8%bv = Z_to_bv 64 d -> WDL.dbl_nz d ->
  (forall i, (i < 4)%nat -> M1 (Z_to_bv 64 (shF + Z.of_nat i)) = Some (Z_to_bv 8 241)) ->
