(* [comment removed for export] *)
Definition RC (Rk : bvmap 5 word) : Prop :=
  getr Rk (reg 2) = Z_to_bv 64 spc /\ getr Rk (reg 3) = getr R (reg 3) /\ getr Rk (reg 4) = getr R (reg 4) /\ getr Rk (reg 26) = getr R (reg 26) /\ getr Rk (reg 27) = getr R (reg 27)
  /\ getr Rk (reg 8) = Z_to_bv 64 sp /\ getr Rk (reg 9) = Z_to_bv 64 spc /\ getr Rk (reg 19) = Z_to_bv 64 so /\ getr Rk (reg 20) = Z_to_bv 64 dp.
Lemma RC_ks Rk Rk' (ks : list nat) : RC Rk -> (forall j, In j ks -> getr Rk' (reg j) = getr Rk (reg j)) ->
  forallb (fun j => existsb (Nat.eqb j) ks) [2; 3; 4; 26; 27; 8; 9; 19; 20]%nat = true -> RC Rk'.
Proof.
