Lemma DBCALL n M3 model3 LK3 Aw3 x g3 cr3 (fx3 : FPState) R3 (len : Z) :
  UINV n M3 model3 LK3 Aw3 x g3 cr3 -> n = 0 -> RC R3 ->
  getr R3 (reg 1) = Z_to_bv 64 0xbe1a0 -> getr R3 (reg 10) = Z_to_bv 64 buf -> getr R3 (reg 11) = Z_to_bv 64 len -> getr R3 (reg 12) = Z_to_bv 64 dp ->
  getr R3 (reg 13) = Z_to_bv 64 so -> 0 <= len <= WDL.SNP_MAX ->
  getr R3 (reg 18) = Z_to_bv 64 F -> getr R3 (reg 25) = Z_to_bv 64 F -> getr R3 (reg 24) = Z_to_bv 64 shF ->
  L5.defined M3 buf len -> (forall a, shF + 4 <= a < shF + 8 -> M3 (Z_to_bv 64 a) = Some (Z_to_bv 8 0)) ->
