(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma SNPCALL n M1 model1 LK1 Aw1 x g1 cr1 (fx1 : FPState) R1 (ra prec d : Z) :
  UINV n M1 model1 LK1 Aw1 x g1 cr1 -> RC R1 ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra ->
  getr R1 (reg 10) = Z_to_bv 64 buf -> getr R1 (reg 11) = Z_to_bv 64 WDL.SNP_BUF -> getr R1 (reg 12) = Z_to_bv 64 VA.FMT_G_A ->
  getr R1 (reg 13) = Z_to_bv 64 prec -> getr R1 (reg 14) = Z_to_bv 64 d -> (prec = 15 \/ prec = 17) -> WDL.dbl_nz d ->
  SH8 M1 shF ->
  (forall (fx3 : FPState) R3 (M3 : mem) model3 (len : Z) (bs : list Z),
      UINV n M3 model3 LK1 Aw1 x g1 cr1 -> (forall j, In j VA.LIBC_CS -> getr R3 (reg j) = getr R1 (reg j)) ->
      getr R3 (reg 10) = Z_to_bv 64 len -> 1 <= len <= WDL.SNP_MAX -> Z.of_nat (length bs) = len ->
      (WDL.gnum bs = true \/ WDL.gspecial bs) -> Forall (fun c => 0 <= c < 256) bs ->
      L5.bytes_at RSEGS M3 buf (bs ++ [0]) -> SH8 M3 shF ->
      (forall a, spc <= a < sp -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 ra M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 SNPC M1 model1) K.
Proof.
