(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma DSCALL M5 model5 LK1 Aw1 x g1 cr1 (fx5 : FPState) R5 (len d : Z) (bs : list Z) :
  UINV 0 M5 model5 LK1 Aw1 x g1 cr1 -> RC R5 ->
  getr R5 (reg 1) = Z_to_bv 64 0xbe148 -> getr R5 (reg 10) = Z_to_bv 64 buf -> getr R5 (reg 11) = Z_to_bv 64 len -> getr R5 (reg 12) = Z_to_bv 64 (spc + 24) ->
  1 <= len <= WDL.SNP_MAX -> Z.of_nat (length bs) = len -> (WDL.gnum bs = true \/ WDL.gspecial bs) -> Forall (fun c => 0 <= c < 256) bs ->
  L5.bytes_at RSEGS M5 buf (bs ++ [0]) ->
  getr R5 (reg 18) = Z_to_bv 64 F -> getr R5 (reg 25) = Z_to_bv 64 F -> getr R5 (reg 24) = Z_to_bv 64 shF ->
  getr R5 (reg 21) = Z_to_bv 64 buf -> getr R5 (reg 22) = Z_to_bv 64 d -> getr R5 (reg 23) = Z_to_bv 64 len -> WDL.dbl_nz d -> SH8 M5 shF ->
